package javax.microedition.lcdui.game;import javax.microedition.lcdui.Graphics;
public class LayerManager{private java.util.Vector layers=new java.util.Vector();private int x,y,w=Integer.MAX_VALUE,h=Integer.MAX_VALUE;public void append(Layer l){if(l==null)throw new NullPointerException();layers.removeElement(l);layers.addElement(l);}public void insert(Layer l,int index){if(l==null)throw new NullPointerException();layers.removeElement(l);layers.insertElementAt(l,index);}public void remove(Layer l){layers.removeElement(l);}public int getSize(){return layers.size();}public Layer getLayerAt(int i){return (Layer)layers.elementAt(i);}public void setViewWindow(int x,int y,int w,int h){if(w<0||h<0)throw new IllegalArgumentException();this.x=x;this.y=y;this.w=w;this.h=h;}public int getViewWindowX(){return x;}public int getViewWindowY(){return y;}public int getViewWindowWidth(){return w;}public int getViewWindowHeight(){return h;}public void paint(Graphics g,int px,int py){int cx=g.getClipX(),cy=g.getClipY(),cw=g.getClipWidth(),ch=g.getClipHeight();g.translate(px-x,py-y);if(w!=Integer.MAX_VALUE)g.clipRect(x,y,w,h);boolean stereo=(crimson.Native.stereoMode()&2)!=0;try{for(int i=layers.size()-1;i>=0;i--){if(stereo)g.stereoLayer(i,layers.size());getLayerAt(i).paint(g);}}finally{if(stereo)g.stereoLayer(-1,0);g.translate(x-px,y-py);g.setClip(cx,cy,cw,ch);}}}
